@@ -62,6 +62,30 @@ server {
         proxy_send_timeout    300s;
     }

+    # GitLab이 Jenkins 배포 Job을 호출하는 Webhook 엔드포인트만 공개한다.
+    # /jenkins/ 이하의 UI·API는 프록시하지 않으므로 기존 SSH 터널 접근 정책은 유지된다.
+    location ^~ /jenkins/project/ {
+        limit_except POST {
+            deny all;
+        }
+
+        # Jenkins 컨테이너가 잠시 재시작 중이어도 nginx 설정 로드는 성공해야 한다.
+        resolver 127.0.0.11 ipv6=off valid=30s;
+        set $jenkins_webhook http://thorp-jenkins:8080;
+
+        # 외부 전용 /jenkins 접두사를 제거해 GitLab Plugin의 /project/...로 전달한다.
+        rewrite ^/jenkins(/project/.*)$ $1 break;
+        proxy_pass $jenkins_webhook;
+        proxy_http_version 1.1;
+        proxy_set_header Host              $host;
+        proxy_set_header X-Real-IP         $remote_addr;
+        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
+        proxy_set_header X-Forwarded-Proto $scheme;
+        proxy_connect_timeout 5s;
+        proxy_read_timeout    30s;
+        proxy_send_timeout    30s;
+    }
+
     root /usr/share/nginx/html;
     index index.html;
